package com.masterlearning.platform.modules.course.repository; import com.masterlearning.platform.modules.course.entity.Enrollment; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface EnrollmentRepository extends JpaRepository<Enrollment,UUID>{boolean existsByCourseIdAndUserId(UUID courseId,UUID userId); Optional<Enrollment> findByCourseIdAndUserId(UUID courseId,UUID userId); List<Enrollment> findByUserId(UUID userId);}